export function mergeWithDmfPoolCandidates(
  dbCandidates: PublicCandidate[] | null | undefined
): PublicCandidate[] {
  if (!dbCandidates || dbCandidates.length === 0) {
    return DMF_POOL_PUBLIC_CANDIDATES;
  }
  const existingIds = new Set(dbCandidates.map((c) => c.id));
  const merged = [
    ...dbCandidates.map((c) => ({
      ...c,
      pool_stage: c.pool_stage ?? (c.visa_status ? "in_germany" : "interview_ready"),
    })),
    ...DMF_POOL_PUBLIC_CANDIDATES.filter((c) => !existingIds.has(c.id)),
  ];
  return merged;
}

export function findDmfPoolCandidateById(id: string): PublicCandidate | null {
  return DMF_POOL_PUBLIC_CANDIDATES.find((c) => c.id === id) ?? null;
}

export function mergeWithDmfAdminCandidates(
  dbCandidates: Candidate[] | null | undefined
): Candidate[] {
  if (!dbCandidates || dbCandidates.length === 0) {
    return DMF_POOL_ADMIN_CANDIDATES;
  }
  const existingIds = new Set(dbCandidates.map((c) => c.id));
  return [...dbCandidates, ...DMF_POOL_ADMIN_CANDIDATES.filter((c) => !existingIds.has(c.id))];
}
